def index_pairs(text, words):
    root = {}
    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {})
        node['$'] = True

    result = []
    n = len(text)
    for i in range(n):
        node = root
        for j in range(i, n):
            ch = text[j]
            if ch not in node:
                break
            node = node[ch]
            if node.get('$'):
                result.append([i, j])

    result.sort()
    return result

